+test('delivers synchronous initial presence and later updates until disposal', () => {
+  const socket = new EventEmitter();
+  socket.connect = () => socket.emit('presence', 'initial');
+  const seen = [];
+  const dispose = connectPresence(socket, value => seen.push(value));
+  socket.emit('presence', 'updated');
+  dispose();
+  socket.emit('presence', 'disposed');
+  assert.deepEqual(seen, ['initial', 'updated']);
+});
+
+test('failed connect cleans up its subscription and preserves the original error', () => {
+  const socket = new EventEmitter();
+  const failure = new Error('connection failed');
+  const seen = [];
+  const existing = value => seen.push(`existing:${value}`);
+  socket.on('presence', existing);
+  socket.connect = () => {
+    socket.emit('presence', 'initial');
+    throw failure;
+  };
+  assert.throws(() => connectPresence(socket, value => seen.push(value)), error => error === failure);
+  assert.deepEqual(socket.listeners('presence'), [existing]);
+  socket.emit('presence', 'later');
+  assert.deepEqual(seen, ['existing:initial', 'initial', 'existing:later']);
+});
+
+test('repeated disposal detaches only its subscription when callbacks are shared', () => {
+  const socket = new EventEmitter();
+  socket.connect = () => {};
+  const seen = [];
+  function callback(...args) {
+    assert.equal(this, socket);
+    seen.push(args);
+  }
+  socket.on('presence', callback);
+  const first = connectPresence(socket, callback);
+  const second = connectPresence(socket, callback);
+  first();
+  first();
+  socket.emit('presence', 'online', 42);
+  assert.deepEqual(seen, [['online', 42], ['online', 42]]);
+  second();
+  assert.deepEqual(socket.listeners('presence'), [callback]);
+});
